# In outbox_list, split %f-last NUL-framed records and guard the conversion:
# script = f'... find {OUTBOX} -mindepth 1 -maxdepth 1 -type f -printf "%s\\t%T@\\t%f\\0"'
out = []
for rec in (res.output[0] or b"").split(b"\0"):
    if not rec:
        continue
    try:
        size_b, mtime_b, name_b = rec.split(b"\t", 2)
        size = int(size_b)
        mtime = float(mtime_b)
    except ValueError:
        continue  # skip malformed / forged entries
    name = name_b.decode("utf-8", errors="replace")
    out.append({"name": name, "bytes": size,
                "mtime": datetime.fromtimestamp(mtime, timezone.utc).isoformat(timespec="seconds")})
return sorted(out, key=lambda x: x["name"])
